import { describe, it, expect } from "vitest";
import {
  MENSAGENS_LOGIN_ADMIN,
  traduzirErroLoginAdmin,
  validarCredenciaisAdmin,
} from "@/lib/adminAuth/regras";

// Spec: SPEC/2026-11-18-login-real-admin.md

describe("validarCredenciaisAdmin", () => {
  it("aceita e-mail e senha preenchidos", () => {
    expect(validarCredenciaisAdmin("admin@complexo.com", "SenhaForte1!")).toBeNull();
  });

  it("ignora espaços nas pontas do e-mail", () => {
    expect(validarCredenciaisAdmin("  admin@complexo.com  ", "x")).toBeNull();
  });

  it("exige e-mail", () => {
    expect(validarCredenciaisAdmin("   ", "senha")).toBe(MENSAGENS_LOGIN_ADMIN.emailObrigatorio);
  });

  it("rejeita e-mail malformado", () => {
    expect(validarCredenciaisAdmin("admin@", "senha")).toBe(MENSAGENS_LOGIN_ADMIN.emailInvalido);
    expect(validarCredenciaisAdmin("admin.com", "senha")).toBe(MENSAGENS_LOGIN_ADMIN.emailInvalido);
  });

  it("exige senha", () => {
    expect(validarCredenciaisAdmin("admin@complexo.com", "")).toBe(MENSAGENS_LOGIN_ADMIN.senhaObrigatoria);
  });
});

describe("traduzirErroLoginAdmin", () => {
  it("credenciais inválidas não revelam se o e-mail existe", () => {
    expect(
      traduzirErroLoginAdmin({ message: "Invalid login credentials", status: 400, code: "invalid_credentials" })
    ).toBe(MENSAGENS_LOGIN_ADMIN.credenciaisInvalidas);
  });

  it("e-mail não confirmado vira credenciais inválidas", () => {
    expect(traduzirErroLoginAdmin({ message: "Email not confirmed", code: "email_not_confirmed" })).toBe(
      MENSAGENS_LOGIN_ADMIN.credenciaisInvalidas
    );
  });

  it("limite de tentativas", () => {
    expect(traduzirErroLoginAdmin({ message: "Request rate limit reached", status: 429 })).toBe(
      MENSAGENS_LOGIN_ADMIN.muitasTentativas
    );
  });

  it("falha de rede", () => {
    expect(traduzirErroLoginAdmin({ name: "AuthRetryableFetchError", message: "Failed to fetch", status: 0 })).toBe(
      MENSAGENS_LOGIN_ADMIN.falhaConexao
    );
    expect(traduzirErroLoginAdmin(new TypeError("Failed to fetch"))).toBe(MENSAGENS_LOGIN_ADMIN.falhaConexao);
  });

  it("erro desconhecido usa mensagem genérica", () => {
    expect(traduzirErroLoginAdmin({ message: "algo estranho", status: 500 })).toBe(MENSAGENS_LOGIN_ADMIN.erroGenerico);
    expect(traduzirErroLoginAdmin(null)).toBe(MENSAGENS_LOGIN_ADMIN.erroGenerico);
  });
});

import { describe, it, expect, vi, beforeEach } from "vitest";
import { MENSAGENS_LOGIN_ADMIN } from "@/lib/adminAuth/regras";

// Spec: SPEC/2026-11-18-login-real-admin.md

const auth = {
  signInWithPassword: vi.fn(),
  signOut: vi.fn(),
  getSession: vi.fn(),
  onAuthStateChange: vi.fn(),
};
const rpc = vi.fn();
let configurado = true;

vi.mock("@/lib/supabase/client", () => ({
  supabase: { auth, rpc },
  isSupabaseConfigured: () => configurado,
}));

import {
  assinarSessaoAdmin,
  entrarComoAdmin,
  sairAdmin,
  verificarSessaoAdmin,
} from "@/lib/supabase/adminAuthService";

const sessao = { access_token: "jwt", user: { id: "uid-1" } };

describe("adminAuthService", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    configurado = true;
    auth.signOut.mockResolvedValue({ error: null });
  });

  describe("entrarComoAdmin", () => {
    it("entra quando a senha confere e o usuário é administrador", async () => {
      auth.signInWithPassword.mockResolvedValue({ data: { session: sessao }, error: null });
      rpc.mockResolvedValue({ data: true, error: null });

      await expect(entrarComoAdmin(" admin@complexo.com ", "Senha1!")).resolves.toEqual({ ok: true });
      expect(auth.signInWithPassword).toHaveBeenCalledWith({ email: "admin@complexo.com", password: "Senha1!" });
      expect(rpc).toHaveBeenCalledWith("is_admin");
      expect(auth.signOut).not.toHaveBeenCalled();
    });

    it("encerra a sessão de quem não é administrador", async () => {
      auth.signInWithPassword.mockResolvedValue({ data: { session: sessao }, error: null });
      rpc.mockResolvedValue({ data: false, error: null });

      await expect(entrarComoAdmin("cliente@x.com", "Senha1!")).resolves.toEqual({
        ok: false,
        erro: MENSAGENS_LOGIN_ADMIN.semPermissao,
      });
      expect(auth.signOut).toHaveBeenCalled();
    });

    it("nega o acesso se a verificação de administrador falhar (falha fechada)", async () => {
      auth.signInWithPassword.mockResolvedValue({ data: { session: sessao }, error: null });
      rpc.mockResolvedValue({ data: null, error: { message: "Failed to fetch" } });

      const resultado = await entrarComoAdmin("admin@complexo.com", "Senha1!");
      expect(resultado.ok).toBe(false);
      expect(auth.signOut).toHaveBeenCalled();
    });

    it("traduz credenciais inválidas", async () => {
      auth.signInWithPassword.mockResolvedValue({
        data: { session: null },
        error: { message: "Invalid login credentials", status: 400, code: "invalid_credentials" },
      });

      await expect(entrarComoAdmin("admin@complexo.com", "errada")).resolves.toEqual({
        ok: false,
        erro: MENSAGENS_LOGIN_ADMIN.credenciaisInvalidas,
      });
      expect(rpc).not.toHaveBeenCalled();
    });

    it("valida os campos antes de chamar o Supabase", async () => {
      await expect(entrarComoAdmin("invalido", "x")).resolves.toEqual({
        ok: false,
        erro: MENSAGENS_LOGIN_ADMIN.emailInvalido,
      });
      expect(auth.signInWithPassword).not.toHaveBeenCalled();
    });

    it("informa quando o Supabase não está configurado", async () => {
      configurado = false;
      await expect(entrarComoAdmin("admin@complexo.com", "Senha1!")).resolves.toEqual({
        ok: false,
        erro: MENSAGENS_LOGIN_ADMIN.naoConfigurado,
      });
      expect(auth.signInWithPassword).not.toHaveBeenCalled();
    });

    it("trata exceção de rede", async () => {
      auth.signInWithPassword.mockRejectedValue(new TypeError("Failed to fetch"));
      await expect(entrarComoAdmin("admin@complexo.com", "Senha1!")).resolves.toEqual({
        ok: false,
        erro: MENSAGENS_LOGIN_ADMIN.falhaConexao,
      });
    });
  });

  describe("verificarSessaoAdmin", () => {
    it("é falso sem sessão, sem consultar a função", async () => {
      auth.getSession.mockResolvedValue({ data: { session: null }, error: null });
      await expect(verificarSessaoAdmin()).resolves.toBe(false);
      expect(rpc).not.toHaveBeenCalled();
    });

    it("é verdadeiro com sessão de administrador", async () => {
      auth.getSession.mockResolvedValue({ data: { session: sessao }, error: null });
      rpc.mockResolvedValue({ data: true, error: null });
      await expect(verificarSessaoAdmin()).resolves.toBe(true);
    });

    it("é falso com sessão de usuário comum ou erro na função", async () => {
      auth.getSession.mockResolvedValue({ data: { session: sessao }, error: null });
      rpc.mockResolvedValueOnce({ data: false, error: null });
      await expect(verificarSessaoAdmin()).resolves.toBe(false);
      rpc.mockResolvedValueOnce({ data: null, error: { message: "erro" } });
      await expect(verificarSessaoAdmin()).resolves.toBe(false);
    });

    it("é falso quando o Supabase não está configurado ou lança exceção", async () => {
      configurado = false;
      await expect(verificarSessaoAdmin()).resolves.toBe(false);
      configurado = true;
      auth.getSession.mockRejectedValue(new Error("boom"));
      await expect(verificarSessaoAdmin()).resolves.toBe(false);
    });
  });

  it("sairAdmin encerra a sessão e não lança em caso de erro", async () => {
    auth.signOut.mockRejectedValue(new Error("rede"));
    await expect(sairAdmin()).resolves.toBeUndefined();
    expect(auth.signOut).toHaveBeenCalled();
  });

  it("assinarSessaoAdmin repassa mudanças e devolve função de cancelamento", () => {
    const unsubscribe = vi.fn();
    let callback: (() => void) | undefined;
    auth.onAuthStateChange.mockImplementation((cb: () => void) => {
      callback = cb;
      return { data: { subscription: { unsubscribe } } };
    });
    const aoMudar = vi.fn();

    const cancelar = assinarSessaoAdmin(aoMudar);
    callback?.();
    expect(aoMudar).toHaveBeenCalledTimes(1);
    cancelar();
    expect(unsubscribe).toHaveBeenCalled();
  });

  it("assinarSessaoAdmin sem Supabase configurado não assina nada", () => {
    configurado = false;
    const cancelar = assinarSessaoAdmin(vi.fn());
    expect(auth.onAuthStateChange).not.toHaveBeenCalled();
    expect(() => cancelar()).not.toThrow();
  });
});

import { describe, it, expect, vi, beforeEach } from "vitest";
import { renderHook, act, waitFor } from "@testing-library/react";

// Spec: SPEC/2026-11-18-login-real-admin.md

const verificarSessaoAdmin = vi.fn();
const entrarComoAdmin = vi.fn();
const sairAdmin = vi.fn();
let aoMudarSessao: (() => void) | undefined;
const cancelarAssinatura = vi.fn();

vi.mock("@/lib/supabase/adminAuthService", () => ({
  verificarSessaoAdmin: () => verificarSessaoAdmin(),
  entrarComoAdmin: (email: string, senha: string) => entrarComoAdmin(email, senha),
  sairAdmin: () => sairAdmin(),
  assinarSessaoAdmin: (cb: () => void) => {
    aoMudarSessao = cb;
    return cancelarAssinatura;
  },
}));

import { useAdminAuth } from "@/hooks/useAdminAuth";

describe("useAdminAuth", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    aoMudarSessao = undefined;
    localStorage.clear();
    sairAdmin.mockResolvedValue(undefined);
  });

  it("começa carregando (null) e reflete a sessão existente", async () => {
    verificarSessaoAdmin.mockResolvedValue(true);
    const { result } = renderHook(() => useAdminAuth());
    expect(result.current.autenticado).toBeNull();
    await waitFor(() => expect(result.current.autenticado).toBe(true));
  });

  it("remove a flag antiga de sessão falsa do localStorage", async () => {
    localStorage.setItem("reservei_admin_auth", "true");
    verificarSessaoAdmin.mockResolvedValue(false);
    const { result } = renderHook(() => useAdminAuth());
    await waitFor(() => expect(result.current.autenticado).toBe(false));
    expect(localStorage.getItem("reservei_admin_auth")).toBeNull();
  });

  it("login com sucesso autentica", async () => {
    verificarSessaoAdmin.mockResolvedValue(false);
    entrarComoAdmin.mockResolvedValue({ ok: true });
    const { result } = renderHook(() => useAdminAuth());
    await waitFor(() => expect(result.current.autenticado).toBe(false));

    let resposta: { ok: boolean; erro?: string } | undefined;
    await act(async () => {
      resposta = await result.current.login("admin@complexo.com", "Senha1!");
    });
    expect(resposta).toEqual({ ok: true });
    expect(entrarComoAdmin).toHaveBeenCalledWith("admin@complexo.com", "Senha1!");
    expect(result.current.autenticado).toBe(true);
  });

  it("login com falha devolve o erro e continua deslogado", async () => {
    verificarSessaoAdmin.mockResolvedValue(false);
    entrarComoAdmin.mockResolvedValue({ ok: false, erro: "E-mail ou senha incorretos." });
    const { result } = renderHook(() => useAdminAuth());
    await waitFor(() => expect(result.current.autenticado).toBe(false));

    let resposta: { ok: boolean; erro?: string } | undefined;
    await act(async () => {
      resposta = await result.current.login("admin@complexo.com", "errada");
    });
    expect(resposta).toEqual({ ok: false, erro: "E-mail ou senha incorretos." });
    expect(result.current.autenticado).toBe(false);
  });

  it("logout encerra a sessão", async () => {
    verificarSessaoAdmin.mockResolvedValue(true);
    const { result } = renderHook(() => useAdminAuth());
    await waitFor(() => expect(result.current.autenticado).toBe(true));

    await act(async () => {
      await result.current.logout();
    });
    expect(sairAdmin).toHaveBeenCalled();
    expect(result.current.autenticado).toBe(false);
  });

  it("revalida quando a sessão muda (ex.: logout em outra aba)", async () => {
    verificarSessaoAdmin.mockResolvedValueOnce(true).mockResolvedValueOnce(false);
    const { result } = renderHook(() => useAdminAuth());
    await waitFor(() => expect(result.current.autenticado).toBe(true));

    await act(async () => {
      aoMudarSessao?.();
    });
    await waitFor(() => expect(result.current.autenticado).toBe(false));
  });

  it("cancela a assinatura ao desmontar", async () => {
    verificarSessaoAdmin.mockResolvedValue(false);
    const { unmount } = renderHook(() => useAdminAuth());
    unmount();
    expect(cancelarAssinatura).toHaveBeenCalled();
  });
});

import React from "react";
import { describe, it, expect, vi } from "vitest";
import { render, screen, fireEvent, waitFor } from "@testing-library/react";
import { AdminLogin } from "@/components/admin/AdminLogin";

// Spec: SPEC/2026-11-18-login-real-admin.md

function preencher(email: string, senha: string) {
  fireEvent.change(screen.getByLabelText("E-mail"), { target: { value: email } });
  fireEvent.change(screen.getByLabelText("Senha"), { target: { value: senha } });
}

describe("AdminLogin", () => {
  it("envia e-mail e senha para o login", async () => {
    const onLogin = vi.fn().mockResolvedValue({ ok: true });
    render(<AdminLogin onLogin={onLogin} />);

    preencher("admin@complexo.com", "Senha1!");
    fireEvent.click(screen.getByRole("button", { name: "Entrar" }));

    await waitFor(() => expect(onLogin).toHaveBeenCalledWith("admin@complexo.com", "Senha1!"));
  });

  it("mostra a mensagem de erro devolvida pelo login e limpa a senha", async () => {
    const onLogin = vi.fn().mockResolvedValue({ ok: false, erro: "Esta conta não tem acesso ao painel administrativo." });
    render(<AdminLogin onLogin={onLogin} />);

    preencher("cliente@x.com", "Senha1!");
    fireEvent.click(screen.getByRole("button", { name: "Entrar" }));

    expect(await screen.findByText("Esta conta não tem acesso ao painel administrativo.")).toBeTruthy();
    expect((screen.getByLabelText("Senha") as HTMLInputElement).value).toBe("");
    expect((screen.getByLabelText("E-mail") as HTMLInputElement).value).toBe("cliente@x.com");
  });

  it("não envia sem e-mail e senha", () => {
    const onLogin = vi.fn();
    render(<AdminLogin onLogin={onLogin} />);
    expect((screen.getByRole("button", { name: "Entrar" }) as HTMLButtonElement).disabled).toBe(true);
    preencher("admin@complexo.com", "");
    expect((screen.getByRole("button", { name: "Entrar" }) as HTMLButtonElement).disabled).toBe(true);
  });

  it("não exibe mais a senha fixa antiga", () => {
    const { container } = render(<AdminLogin onLogin={vi.fn()} />);
    expect(container.innerHTML).not.toContain("admin123");
  });
});

