/**
 * Regras puras do login do painel administrativo: validação dos campos e
 * tradução dos erros do Supabase Auth para mensagens em português.
 *
 * Spec: SPEC/2026-11-18-login-real-admin.md
 */

export const MENSAGENS_LOGIN_ADMIN = {
  emailObrigatorio: "Informe o e-mail de acesso.",
  emailInvalido: "Informe um e-mail válido.",
  senhaObrigatoria: "Informe a senha.",
  credenciaisInvalidas: "E-mail ou senha incorretos.",
  semPermissao: "Esta conta não tem acesso ao painel administrativo.",
  muitasTentativas: "Muitas tentativas seguidas. Aguarde alguns minutos e tente novamente.",
  falhaConexao: "Não foi possível conectar ao servidor. Verifique sua internet e tente novamente.",
  naoConfigurado: "Login indisponível: o Supabase não está configurado neste ambiente.",
  erroGenerico: "Não foi possível entrar agora. Tente novamente em instantes.",
} as const;

const REGEX_EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/**
 * Valida os campos antes de chamar o Supabase.
 *
 * @returns Mensagem de erro, ou `null` quando os campos são válidos.
 */
export function validarCredenciaisAdmin(email: string, senha: string): string | null {
  const emailLimpo = email.trim();
  if (!emailLimpo) return MENSAGENS_LOGIN_ADMIN.emailObrigatorio;
  if (!REGEX_EMAIL.test(emailLimpo)) return MENSAGENS_LOGIN_ADMIN.emailInvalido;
  if (!senha) return MENSAGENS_LOGIN_ADMIN.senhaObrigatoria;
  return null;
}

interface ErroAuth {
  name?: string;
  message?: string;
  status?: number;
  code?: string;
}

/**
 * Converte um erro do Supabase Auth (ou de rede) em mensagem para o usuário.
 * Credenciais erradas e e-mail não confirmado recebem a mesma mensagem, para
 * não revelar quais e-mails têm conta.
 */
export function traduzirErroLoginAdmin(erro: unknown): string {
  if (!erro || typeof erro !== "object") return MENSAGENS_LOGIN_ADMIN.erroGenerico;

  const { name = "", message = "", status, code = "" } = erro as ErroAuth;
  const texto = `${code} ${message}`.toLowerCase();

  if (code === "invalid_credentials" || code === "email_not_confirmed" || texto.includes("invalid login credentials") || texto.includes("email not confirmed")) {
    return MENSAGENS_LOGIN_ADMIN.credenciaisInvalidas;
  }
  if (status === 429 || texto.includes("rate limit")) {
    return MENSAGENS_LOGIN_ADMIN.muitasTentativas;
  }
  if (name === "AuthRetryableFetchError" || status === 0 || texto.includes("failed to fetch") || texto.includes("network")) {
    return MENSAGENS_LOGIN_ADMIN.falhaConexao;
  }
  return MENSAGENS_LOGIN_ADMIN.erroGenerico;
}

/**
 * Autenticação do painel administrativo com o Supabase Auth.
 *
 * Login por e-mail e senha + verificação de permissão pela função
 * `public.is_admin()` (tabela `administradores`). Ter conta no Auth não basta.
 *
 * Spec: SPEC/2026-11-18-login-real-admin.md
 */

import { supabase, isSupabaseConfigured } from "./client";
import {
  MENSAGENS_LOGIN_ADMIN,
  traduzirErroLoginAdmin,
  validarCredenciaisAdmin,
} from "@/lib/adminAuth/regras";

export type ResultadoLoginAdmin = { ok: true } | { ok: false; erro: string };

/** Consulta `is_admin()` para a sessão atual. Qualquer falha nega o acesso. */
async function sessaoEhAdmin(): Promise<boolean> {
  const { data, error } = await supabase.rpc("is_admin");
  if (error) {
    console.warn("[AdminAuth] Falha ao verificar permissão de administrador:", error.message);
    return false;
  }
  return data === true;
}

/**
 * Faz login com e-mail e senha e confirma que a conta é de administrador.
 * Se a conta não for de administrador, a sessão aberta é encerrada.
 */
export async function entrarComoAdmin(email: string, senha: string): Promise<ResultadoLoginAdmin> {
  const erroValidacao = validarCredenciaisAdmin(email, senha);
  if (erroValidacao) return { ok: false, erro: erroValidacao };
  if (!isSupabaseConfigured()) return { ok: false, erro: MENSAGENS_LOGIN_ADMIN.naoConfigurado };

  try {
    const { data, error } = await supabase.auth.signInWithPassword({
      email: email.trim(),
      password: senha,
    });
    if (error || !data.session) {
      return { ok: false, erro: traduzirErroLoginAdmin(error) };
    }

    if (await sessaoEhAdmin()) return { ok: true };

    await sairAdmin();
    return { ok: false, erro: MENSAGENS_LOGIN_ADMIN.semPermissao };
  } catch (err) {
    console.warn("[AdminAuth] Erro inesperado no login:", err);
    return { ok: false, erro: traduzirErroLoginAdmin(err) };
  }
}

/** Indica se existe sessão ativa de um administrador. */
export async function verificarSessaoAdmin(): Promise<boolean> {
  if (!isSupabaseConfigured()) return false;
  try {
    const { data } = await supabase.auth.getSession();
    if (!data.session) return false;
    return await sessaoEhAdmin();
  } catch (err) {
    console.warn("[AdminAuth] Erro ao verificar a sessão:", err);
    return false;
  }
}

/** Encerra a sessão. Erros de rede são registrados e não interrompem o logout local. */
export async function sairAdmin(): Promise<void> {
  try {
    await supabase.auth.signOut();
  } catch (err) {
    console.warn("[AdminAuth] Erro ao encerrar a sessão:", err);
  }
}

/**
 * Escuta mudanças de sessão (login, logout, expiração, outras abas).
 * @returns Função para cancelar a assinatura.
 */
export function assinarSessaoAdmin(aoMudar: () => void): () => void {
  if (!isSupabaseConfigured()) return () => {};
  const {
    data: { subscription },
  } = supabase.auth.onAuthStateChange(() => aoMudar());
  return () => subscription.unsubscribe();
}

/**
 * Estado de autenticação do painel administrativo (Supabase Auth + is_admin()).
 *
 * `autenticado` é `null` enquanto a sessão está sendo verificada.
 *
 * Spec: SPEC/2026-11-18-login-real-admin.md
 */

"use client";

import { useState, useEffect, useCallback } from "react";
import {
  assinarSessaoAdmin,
  entrarComoAdmin,
  sairAdmin,
  verificarSessaoAdmin,
  type ResultadoLoginAdmin,
} from "@/lib/supabase/adminAuthService";

/** Flag da autenticação simulada antiga (AP1), removida ao carregar. */
const CHAVE_SESSAO_ANTIGA = "reservei_admin_auth";

export function useAdminAuth() {
  const [autenticado, setAutenticado] = useState<boolean | null>(null);

  useEffect(() => {
    let ativo = true;

    try {
      localStorage.removeItem(CHAVE_SESSAO_ANTIGA);
    } catch {
      // localStorage indisponível (modo privado): nada a limpar.
    }

    const verificar = async () => {
      const ehAdmin = await verificarSessaoAdmin();
      if (ativo) setAutenticado(ehAdmin);
    };

    void verificar();
    const cancelar = assinarSessaoAdmin(() => void verificar());

    return () => {
      ativo = false;
      cancelar();
    };
  }, []);

  const login = useCallback(async (email: string, senha: string): Promise<ResultadoLoginAdmin> => {
    const resultado = await entrarComoAdmin(email, senha);
    if (resultado.ok) setAutenticado(true);
    return resultado;
  }, []);

  const logout = useCallback(async () => {
    await sairAdmin();
    setAutenticado(false);
  }, []);

  return { autenticado, login, logout };
}

